mapper.insert:
INSERT INTO homepage_ip_flag_state AS state (day, ip, observed) SELECT #{day}, CAST(input.ip AS inet), input.mask FROM (VALUES
(CAST(#{row.ip} AS text), CAST(#{row.mask} AS integer))
) AS input(ip, mask) WHERE NOT EXISTS ( SELECT 1 FROM homepage_ip_flag_state existing WHERE existing.day = #{day} AND existing.ip = CAST(input.ip AS inet) AND (existing.observed & input.mask) = input.mask ) ORDER BY input.ip COLLATE "C" ON CONFLICT (day, ip) DO UPDATE SET observed = state.observed | EXCLUDED.observed WHERE (state.observed & EXCLUDED.observed) <> EXCLUDED.observed
